{
  "name": "楔形图形区域组件",
  "name_en": "Wedge Graphic Component",
  "manufacturer": "",
  "description": "用于科学图像或实验数据界面中的非物理图形组件，表示可编辑的楔形选区/掩膜。它支持角度范围定义、拖拽调整、命中测试、区域与掩膜生成，以及剪贴板或拖放相关的数据序列化，常用于图像分析中的扇区选择与标注。",
  "description_en": "A non-physical graphical component used in scientific imaging or experimental data interfaces to represent an editable wedge-shaped region of interest or mask. It supports angle-range definition, drag-based editing, hit testing, region and mask generation, and serialization for clipboard or drag-and-drop use, typically for sector selection and annotation in image analysis.",
  "actions": [
    {
      "action_name": "auto-angle_interval",
      "description": "获取或设置楔形的角度区间。",
      "description_en": "Get or set the wedge angle interval."
    },
    {
      "action_name": "auto-mime_data_dict",
      "description": "导出楔形图形的 MIME 数据字典，用于复制、粘贴或拖放。",
      "description_en": "Export a MIME data dictionary for the wedge graphic for copy, paste, or drag-and-drop."
    },
    {
      "action_name": "auto-read_from_mime_data",
      "description": "从 MIME 数据字典读取并恢复楔形图形状态。",
      "description_en": "Read and restore the wedge graphic state from a MIME data dictionary."
    },
    {
      "action_name": "auto-get_attributes",
      "description": "获取楔形图形的显示或编辑属性。",
      "description_en": "Get display or editing attributes of the wedge graphic."
    },
    {
      "action_name": "auto-used_role",
      "description": "获取该楔形图形在界面或分析中的使用角色。",
      "description_en": "Get the usage role of the wedge graphic in the interface or analysis."
    },
    {
      "action_name": "auto-start_angle",
      "description": "获取或设置楔形的起始角度。",
      "description_en": "Get or set the start angle of the wedge."
    },
    {
      "action_name": "auto-end_angle",
      "description": "获取或设置楔形的结束角度。",
      "description_en": "Get or set the end angle of the wedge."
    },
    {
      "action_name": "auto-test",
      "description": "测试给定位置是否命中楔形图形或其可编辑部分。",
      "description_en": "Test whether a given position hits the wedge graphic or one of its editable parts."
    },
    {
      "action_name": "auto-begin_drag",
      "description": "开始楔形图形的拖拽编辑操作。",
      "description_en": "Begin a drag-edit operation for the wedge graphic."
    },
    {
      "action_name": "auto-end_drag",
      "description": "结束楔形图形的拖拽编辑并提交结果。",
      "description_en": "End the drag-edit operation for the wedge graphic and commit the result."
    },
    {
      "action_name": "auto-adjust_part",
      "description": "在交互编辑过程中调整楔形图形的某一部分。",
      "description_en": "Adjust a specific part of the wedge graphic during interactive editing."
    },
    {
      "action_name": "auto-get_region",
      "description": "生成与该楔形图形对应的区域对象。",
      "description_en": "Generate the region object corresponding to the wedge graphic."
    },
    {
      "action_name": "auto-get_mask_item",
      "description": "生成与该楔形图形对应的掩膜项。",
      "description_en": "Generate the mask item corresponding to the wedge graphic."
    },
    {
      "action_name": "auto-label_position",
      "description": "计算楔形图形标签在界面中的显示位置。",
      "description_en": "Compute the display position of the wedge graphic label in the interface."
    },
    {
      "action_name": "auto-validate_angles",
      "description": "校验并规范化楔形的角度参数。",
      "description_en": "Validate and normalize the wedge angle parameters."
    },
    {
      "action_name": "auto-draw_mask",
      "description": "绘制该楔形区域对应的掩膜。",
      "description_en": "Draw the mask corresponding to the wedge region."
    }
  ],
  "tag_hints": [
    "graphical ROI",
    "wedge region",
    "image annotation",
    "mask generation",
    "interactive drag editing",
    "hit testing",
    "scientific imaging UI"
  ]
}

